CREATE DATABASE IF NOT EXISTS Agribusiness CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE Agribusiness;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30) NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('farmer','buyer','admin') NOT NULL DEFAULT 'buyer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(255) NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS produce (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farmer_id INT UNSIGNED NOT NULL,category_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL DEFAULT 0,unit ENUM('kg','bunch','piece','crate','bag','litre') NOT NULL DEFAULT 'kg',location VARCHAR(150) NOT NULL,photo VARCHAR(500) NULL,description TEXT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_produce_farmer FOREIGN KEY(farmer_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_produce_category FOREIGN KEY(category_id) REFERENCES categories(id),INDEX idx_produce_status(status),INDEX idx_produce_name(name)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,buyer_id INT UNSIGNED NOT NULL,total DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('pending_approval','placed','confirmed','dispatched','delivered','rejected','cancelled') NOT NULL DEFAULT 'pending_approval',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_orders_buyer FOREIGN KEY(buyer_id) REFERENCES users(id),INDEX idx_orders_status(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id INT UNSIGNED NOT NULL,produce_id INT UNSIGNED NOT NULL,farmer_id INT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,unit_price DECIMAL(10,2) NOT NULL,CONSTRAINT fk_items_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,CONSTRAINT fk_items_produce FOREIGN KEY(produce_id) REFERENCES produce(id),CONSTRAINT fk_items_farmer FOREIGN KEY(farmer_id) REFERENCES users(id),INDEX idx_items_farmer(farmer_id)) ENGINE=InnoDB;
